def cdma_send(chips, sends):
    """把各站的码片按发送数据叠加成公共信道信号。"""
    n = len(next(iter(chips.values())))
    signal = [0] * n
    for name, chip in chips.items():
        v = sends.get(name)
        if v is None:                 # 静默：不发，对信道无贡献
            continue
        sign = 1 if v == 1 else -1    # 发 0 用反码
        for i in range(n):
            signal[i] += sign * chip[i]
    return signal


def cdma_decode(signal, chip):
    """内积 / 码片长度 -> 三态解码。"""
    dot = sum(s * c for s, c in zip(signal, chip))
    value = dot / len(chip)
    if value > 0.5:
        return dot, 1
    if value < -0.5:
        return dot, 0
    return dot, None                  # 0 -> 静默（关键：不是「收到 0」）


if __name__ == '__main__':
    chips = {'A': [1, 1, 1, 1], 'B': [1, 1, -1, -1],
             'C': [1, -1, 1, -1], 'D': [1, -1, -1, 1]}
    sends = {'A': 1, 'B': 0, 'C': None, 'D': 1}
    sig = cdma_send(chips, sends)
    print('信号 =', sig)
    for k in 'ABCD':
        print(k, cdma_decode(sig, chips[k]))
